import csv
import logging
import os.path

logger = logging.getLogger(__name__)


class csvhandling ():
    def __init__(self):
        pass

    #Outputs array with row data  as dictionary
    #Eg [{'Sequence':'IMRT','Beam':'IMRT 10 X 10 cm 10 X 3 MU 180 Degrees'},{'Sequence':'IMRT','Beam':'IMRT 10 X 10 cm 10 X 3 MU 270 Degrees'}]
    def csv_read(self,path_to_file):
        csv_data =[]
        with open(path_to_file) as input_file:
            reader = csv.DictReader(input_file)
            for row in reader:
                csv_data.append(row)
            return csv_data

    #Writes a csv file with defined headers as an array and result data as a array of dictionaries
    # eg [[{'Sequence':'IMRT','Beam':'IMRT 10 X 10 cm 10 X 3 MU 180 Degrees'},{'Sequence':'IMRT','Beam':'IMRT 10 X 10 cm 10 X 3 MU 270 Degrees'}]]
    def csv_write(self,headers,path_to_file,result_data):
        with open(path_to_file,"w") as output_file:
            writer = csv.DictWriter(output_file,headers)
            writer.writeheader()
            writer.writerows(result_data)


    def csv_write_or_append(self,headers,path_to_file,result_data):

        if os.path.exists(path_to_file) and os.path.isfile(path_to_file):
            with open(path_to_file, 'a') as output_file:
                writer = csv.DictWriter(output_file,headers)
                writer.writerows(result_data)
        else:
            self.csv_write(headers,path_to_file,result_data)


    @staticmethod
    def iterateObjectsFromCsv(listOfClasses,csv_path):
        logger.debug("iterateObjectsFromCsv: " + str(listOfClasses) + ", " + str(csv_path))
        tuple_list = csvhandling.getObjectsFromCsv(listOfClasses,csv_path)
        for tup in tuple_list:
            yield tup

    #Generic function to generate a collection of objects defined by the module, class
    #and data held in csv file.
    #Expect this would ordinarily live in the CSV module that Neil has created.
    @staticmethod
    def getObjectsFromCsv(listOfClasses,csv_path):

        objects_from_file = []
        logger.debug("Sourcing testdata from : " + csv_path)
        csv_file = open(csv_path,"r")
        all_rows = csv.DictReader(csv_file)

        for data_row in all_rows:
            domain_instances = []
            for clazz in listOfClasses:
                module_name, class_name = clazz.split(".")
                #Create new object instance using given module and class names, injecting data_row
                instance = csvhandling.get_instance_from_class(module_name,class_name,data_row)
                domain_instances.append(instance)
                #add new instance to collection
            objects_from_file.append(tuple(domain_instances))
        return objects_from_file


    #Utility function to create an object instance from the given
    #module and class names, and __init_ fields.
    #Returns specified class instance.
    @staticmethod
    def get_instance_from_class(module_name, class_name, *init_fields):
        import importlib
        instance = None
        try:
            module = importlib.import_module(module_name)
            try:
                instance = getattr(module, class_name)(*init_fields)
            except AttributeError:
                logging.error('Class not found')
        except ImportError:
            logging.error('Module not found')
        return instance or None



def loadListFromFile(source_path):
    loaded_list = []
    try:
        file_source = open(source_path,'r')
        for line in file_source:
            loaded_list.append(line.strip())

        file_source.close()
    except Exception as e:
        logging.exception("Problem loading list from file." )

    logger.debug("Loaded list from file " + source_path)
    return loaded_list
